{
  "version": "schemaxis.readiness/1",
  "routes": {
    "schemaxis.imagej/1": {
      "guide": "docs/imagej.md",
      "context": {
        "purpose": "Threshold one calibrated 8/16-bit grayscale image with headless ImageJ 1.54 and publish verified per-particle measurements (pixel count, area, centroid, bounding box and raw intensity mean/min/max) in declared physical units, ready for Calc or a later R analysis. A second operation, measureRegions, applies one named rectangle list to 2-8 captured planes with declared frame IDs and times and publishes a labelled per-frame, per-region table.",
        "assumptions": "ImageJ 1.54 ij.jar (latest release 1.54t qualified) run by a Java 11+ runtime with the jdk.compiler module; a fixed Java source program uses public ImageJ classes headlessly with isolated preferences. Declared pixel width/height and unit replace any calibration stored in the file. Thresholds are inclusive raw stored intensities.",
        "constraints": "One .pgm (P5, maxval 255 or 65535) or uncompressed single-IFD BlackIsZero 8/16-bit unsigned .tif/.tiff, at most 2048 px per side, 1048576 px and 16 MiB; no colour, stacks, ROI, density calibration or inverted LUT. Manual inclusive threshold only; full-range thresholds are rejected. Eight or four connectivity; four requires includeHoles. Size filter is converted to inclusive whole-pixel counts. At least one and at most 4096 particles. Units nm, um, mm, cm or m; pixel size 1e-6..1e6 per side. No arbitrary macros, scripts, plugins or Fiji launcher. measureRegions: 2-8 same-size, same-depth planes (4194304 px and 32 MiB total), 1-16 zero-based top-left integer rectangles (right/bottom exclusive, fully inside every frame, overlap allowed), safe unique frame/region IDs, strictly increasing finite seconds; no thresholds, motion, registration or overlay.",
        "inspection": "particles.csv has one row per particle in ImageJ raster order with unit-bearing column names. particle-summary.json retains image digest/format/bit depth, calibration and coordinate convention, threshold, connectivity, filters, rejected counts, totals and area fraction. count-mask.pgm, native tables and readbacks remain as evidence.",
        "recovery": "INVALID_THRESHOLD: order the bounds and stay within the image bit depth; do not select every pixel. UNSUPPORTED_OPTION: four connectivity needs includeHoles true. INVALID_SIZE_FILTER: widen the area window to contain a whole pixel count. NO_PARTICLES: inspect thresholdPixels and rejected counts, then adjust threshold or filters. INVALID_IMAGE/UNSUPPORTED_IMAGE: convert to a supported plain grayscale PGM/TIFF. INTERPRETER_NOT_FOUND: configure Java (imagej) and ij.jar (imagejJar). UNSUPPORTED_RUNTIME: use ImageJ 1.54 and Java 11+. VERIFICATION_FAILED: keep the run directory and start a fresh attempt. DUPLICATE_FRAME_ID/DUPLICATE_REGION_ID/INVALID_IDENTIFIER: use unique safe IDs. NON_INCREASING_TIME: list frames in strictly increasing seconds. REGION_OUT_OF_BOUNDS: keep each rectangle inside every frame. SERIES_MISMATCH: supply equal width, height and bit depth. RESOURCE_LIMIT: reduce the series or rectangles."
      },
      "examples": [
        {
          "id": "baseline",
          "reference": "examples/schemaxis/imagej-particles.json"
        },
        {
          "id": "filled",
          "reference": "examples/schemaxis/imagej-particles-filled.json"
        },
        {
          "id": "sixteen-bit",
          "reference": "examples/schemaxis/imagej-particles-16bit.json"
        },
        {
          "id": "four-without-holes",
          "document": {
            "version": "schemaxis.imagej/1",
            "operation": "analyzeParticles",
            "image": "/replace-with-your-input/particles-8bit.pgm",
            "calibration": {
              "pixelWidth": 0.5,
              "pixelHeight": 0.5,
              "unit": "um"
            },
            "threshold": {
              "lower": 100,
              "upper": 255
            },
            "connectivity": "four",
            "includeHoles": false,
            "excludeEdges": false,
            "minimumArea": 0
          },
          "expect": "invalid",
          "fault": "UNSUPPORTED_OPTION",
          "schemaValid": true
        },
        {
          "id": "inverted-threshold",
          "document": {
            "version": "schemaxis.imagej/1",
            "operation": "analyzeParticles",
            "image": "/replace-with-your-input/particles-8bit.pgm",
            "calibration": {
              "pixelWidth": 0.5,
              "pixelHeight": 0.5,
              "unit": "um"
            },
            "threshold": {
              "lower": 200,
              "upper": 100
            },
            "connectivity": "eight",
            "includeHoles": false,
            "excludeEdges": false,
            "minimumArea": 0
          },
          "expect": "invalid",
          "fault": "INVALID_THRESHOLD",
          "schemaValid": true
        },
        {
          "id": "relative-image",
          "document": {
            "version": "schemaxis.imagej/1",
