              }
            ],
            "calibration": {
              "pixelWidth": 0.5,
              "pixelHeight": 2,
              "unit": "um"
            },
            "macro": "run(\"Measure\");"
          },
          "expect": "invalid",
          "fault": "UNKNOWN_ARGUMENT",
          "schemaValid": false
        }
      ],
      "conformance": [
        "tests/unit/test_imagej_admission.py"
      ],
      "acceptance": [
        "tools/qualify_imagej.py",
        "tools/qualify_imagej_fixtures.py",
        "tools/qualify_imagej_regions.py",
        "tools/qualify_imagej_series_fixtures.py"
      ],
      "profiles": {
        "workflow": {
          "scope": "Verified particle table into Calc (readCSV) with preserved unit-bearing column names; keep the summary for calibration and threshold provenance.",
          "references": [
            "docs/imagej.md",
            "examples/schemaxis/imagej-to-calc.json",
            "tools/qualify_imagej.py"
          ]
        },
        "composition": {
          "scope": "Shared document references, pure value functions and expressions resolve for every finite analytic visit before native validation.",
          "references": [
            "docs/adaptor-runtime.md",
            "tests/unit/test_adaptor_runtime.py"
          ]
        }
      },
      "development": {
        "api": [
          "https://imagej.net/ij/developer/api/ij/ij/plugin/filter/ParticleAnalyzer.html",
          "https://imagej.net/ij/developer/api/ij/ij/measure/Calibration.html",
          "https://imagej.net/ij/developer/api/ij/ij/process/ImageStatistics.html",
          "https://imagej.net/ij/developer/api/ij/ij/plugin/PGM_Reader.html",
          "https://imagej.net/ij/developer/api/ij/ij/io/Opener.html",
          "https://imagej.net/ij/docs/menus/analyze.html",
          "https://imagej.net/ij/download.html",
          "https://openjdk.org/jeps/330",
          "https://imagej.net/ij/developer/api/ij/ij/ImageStack.html",
          "https://imagej.net/ij/developer/api/ij/ij/ImagePlus.html",
          "https://imagej.net/ij/developer/api/ij/ij/gui/Roi.html"
        ],
        "lifecycle": {
          "timeout": "One deadline covers Java identification, the analyse stage and the fresh reopen stage; the shared kit watchdog bounds the whole attempt and a final deadline check bounds host verification.",
          "cancellation": "Shared owned-process cancellation with checks before each native stage and before publication; no resident ImageJ process.",
          "logs": "Retain authored/effective plans, the copied input image, fixed Java program, runtime record, java -version output, both stage submissions/stdout/stderr, native readbacks, native and reopened tables, count mask, publications and failure results.",
          "verification": "An independent dependency-free PGM/TIFF decoder and connected-component model (raster order, inclusive threshold, 8/4 connectivity, enclosed-hole fill, bounding-box edge exclusion, whole-pixel size window) predicts every particle. Native ParticleAnalyzer rows, every count-mask label and a fresh-process ImageStatistics re-measurement of each label must match within 1e-12 relative. Native readback confirms ImageJ version, decoded dimensions/depth/plane count, consumed input digest, declared calibration and unit, threshold and analyser options. Publications and evidence are digest-bound and the summary is recomputed. measureRegions: an independent exact enumeration of every pixel of every rectangle in every captured frame (integer count, minimum, maximum, Fraction mean; area and geometry within 1e-12 relative) checks ImageStatistics rows and a fresh-process ImagePlus/Roi readback, which also reads back frame labels and rectangle names, calibration and source digests."
        },
        "data": [
          {
            "id": "image",
            "direction": "input",
            "kind": "image",
            "format": "PGM (P5) or uncompressed baseline TIFF",
            "traits": {
              "channels": 1,
              "bitDepth": "8 or 16 unsigned",
              "calibration": "declared, not read from file"
            },
            "losses": [
              "File calibration, display range, LUT and metadata are not used; only raw stored intensities."
            ],
            "scope": "One grayscale plane up to 2048 px per side and 1048576 px."
          },
          {
            "id": "particles",
            "direction": "output",
            "kind": "table",
            "format": "numeric CSV",
            "traits": {
              "units": "declared length unit in column names; areas in unit^2; intensities raw",
              "rows": "1-4096 particles in raster order"
            },
            "losses": [
              "Per-particle scalar measurements only; no outlines, perimeter, shape descriptors or pixel lists.",
              "CSV alone omits threshold, connectivity and image provenance; keep the summary."
            ],
            "scope": "Particle label, pixel count, calibrated area, centroid and bounds, raw mean/min/max."
          },
          {
            "id": "summary",
            "direction": "output",
            "kind": "text",
            "format": "JSON",
            "traits": {
              "provenance": "image SHA-256, ImageJ and Java versions",
              "units": "declared"
            },
            "losses": [
              "Totals and fractions describe this image and threshold only; no statistical inference or segmentation-quality claim."
            ],
            "scope": "Calibration and coordinate convention, threshold, connectivity, filters, rejected counts, totals and area fraction."
          },
          {
            "id": "frames",
            "direction": "input",
            "kind": "image",
            "format": "2-8 PGM (P5) or uncompressed baseline TIFF planes",
            "traits": {
              "channels": 1,
              "bitDepth": "8 or 16 unsigned, identical across frames",
              "dimensions": "identical width and height across frames",
              "time": "declared seconds, strictly increasing",
              "calibration": "declared, not read from file"
            },
            "losses": [
              "File calibration, display range, LUT and metadata are not used; only raw stored intensities.",
              "Frames are not registered, resampled or aligned; the same pixel coordinates are measured in every frame."
            ],
            "scope": "Series of at most 8 planes; at most 4194304 pixels and 32 MiB in total, each plane within the single-image limits."
          },
          {
            "id": "region-measurements",
            "direction": "output",
            "kind": "file",
            "format": "labelled CSV (text frame and region identifiers)",
            "traits": {
              "units": "area in declared unit^2; intensities raw; time in seconds",
              "rows": "frames x regions, frame-major in declared order"
            },
            "losses": [
              "Per-record scalar measurements only; no sums, centroids, outlines, overlay or editable ROI set.",
              "CSV alone omits source hashes, calibration and conventions; keep the JSON record."
            ],
            "scope": "Frame, region, time, pixel count, calibrated area and raw mean/minimum/maximum for at most 128 records."
          },
          {
            "id": "region-summary",
            "direction": "output",
            "kind": "text",
            "format": "JSON",
            "traits": {
              "provenance": "every frame SHA-256, ImageJ and Java versions",
              "units": "declared"
            },
            "losses": [
              "Describes these frames and rectangles only; no tracking, registration or biological or materials inference."
            ],
            "scope": "Series geometry, frame identity and time, region geometry, calibration and conventions, overlap statement, every record."
          }
        ],
        "inspection": [
          {
            "panel": "table",
            "scope": "Inspect per-particle measurements with unit-bearing columns.",
            "limits": "At most 4096 rows; no overlay of outlines on the image."
          },
          {
            "panel": "text",
            "scope": "Review calibration, threshold, connectivity, filters, rejected counts and totals in the summary.",
            "limits": "Bounded JSON; the count mask is retained evidence, not an interactive viewer."
          },
          {
            "panel": "table",
            "scope": "Inspect labelled per-frame, per-region records.",
            "limits": "At most 128 records; text identifiers need a typed consumer such as Calc readTypedCSV; no overlay."
          }
        ],
        "authoring": {
          "model": "document",
          "example": "baseline",
          "reuse": "Edit the shared JSON source or property pointers for image path, calibration, threshold, connectivity and filters; plan a fresh revision, execute, inspect and verify."
        },
        "features": {
          "native-inspection": {
            "status": "unsupported",
            "scope": "This bounded batch particle route does not implement native-inspection."
          },
          "mpi": {
            "status": "unsupported",
            "scope": "This bounded batch particle route does not implement mpi."
          },
          "time-batches": {
            "status": "unsupported",
            "scope": "This bounded batch particle route does not implement time-batches."
          },
          "live-editing": {
            "status": "unsupported",
            "scope": "This bounded batch particle route does not implement live-editing."
          },
          "native-save": {
            "status": "unsupported",
            "scope": "This bounded batch particle route does not implement native-save."
          },
          "conversion": {
            "status": "unsupported",
            "scope": "This bounded batch particle route does not implement conversion."
          },
          "workflow": {
            "status": "supported",
            "scope": "Verified particle table into Calc (readCSV) with preserved unit-bearing column names; keep the summary for calibration and threshold provenance. measureRegions: the labelled CSV is a generic file artifact for Calc readTypedCSV with explicit text and numeric columns."
          },
          "composition": {
            "status": "supported",
            "scope": "Shared document references, pure value functions and expressions resolve for every finite analytic visit before native validation."
          },
          "reusable-inputs": {
            "status": "supported",
            "scope": "The input image digest and authored settings identify an attempt; a changed image file prevents reuse. For measureRegions every frame path is bound to its digest, so changing one frame invalidates the attempt."
          },
          "source-authoring": {
            "status": "supported",
            "scope": "Shared durable document JSON editing and undo."
          },
          "property-authoring": {
            "status": "supported",
            "scope": "Shared JSON pointer edits for image path, calibration, threshold and filters."
          }
        },
        "cases": [
          {
            "id": "baseline-8bit",
            "example": "baseline",
            "edits": [],
            "resources": {
              "/image": "examples/schemaxis/fixtures/imagej/particles-8bit.pgm"
            },
            "scope": "Synthetic 64x48 8-bit target, threshold [100,255], 8-connected, 0.5 um square pixels. Eight particles of 20, 60, 64, 1, 72, 108, 4 and 18 pixels (347 px = 86.75 um^2). The ring excludes its 6x6 hole and the 2x2 island inside it is a separate particle; corner-touching 3x3 squares form one 18-pixel particle. Centroids are pixel-centre means; the L shape is ((588/72)+0.5, (1956/72)+0.5)*0.5 um.",
            "checks": [
              {
                "file": "particle-summary.json",
                "format": "json",
                "pointer": "/particleCount",
                "expected": 8,
                "absolute": 1e-12,
                "relative": 1e-12
              },
              {
                "file": "particle-summary.json",
                "format": "json",
                "pointer": "/totalPixels",
                "expected": 347,
                "absolute": 1e-12,
                "relative": 1e-12
              },
              {
                "file": "particle-summary.json",
                "format": "json",
                "pointer": "/totalArea",
                "expected": 86.75,
                "absolute": 1e-12,
                "relative": 1e-12
              },
              {
                "file": "particles.csv",
                "format": "csv",
                "pointer": "/rows/4",
                "expected": [
                  5,
                  72,
                  18,
                  4.333333333333333,
                  13.833333333333334,
                  2,
                  12,
                  6,
                  5,
                  220,
                  220,
                  220
                ],
                "absolute": 1e-12,
                "relative": 1e-12
              },
              {
                "file": "particles.csv",
                "format": "csv",
                "pointer": "/rows/5",
                "expected": [
                  6,
                  108,
                  27,
                  23,
                  16,
                  20,
                  13,
                  6,
                  6,
                  160,
                  160,
                  160
                ],
                "absolute": 1e-12,
                "relative": 1e-12
              },
              {
                "file": "particles.csv",
                "format": "csv",
